method='''    private void showTabletMeasurements() {\n        clearBody("Měření", "OBVOD / PRVEK → měřicí body → spojitost → RCD / RCBO");\n        addRevisionContext();\n        List<Db.Row> all = db.measurements(revisionId);\n        List<Db.Row> rows = new ArrayList<>();\n        for (Db.Row r : all) if (!"BLANK".equals(measurementRowType(r))) rows.add(r);\n        LinearLayout columns = tabletColumns();\n        LinearLayout list = tabletPanel(columns, 6);\n        LinearLayout detail = tabletPanel(columns, 5);\n\n        LinearLayout top = new LinearLayout(this); top.setOrientation(LinearLayout.HORIZONTAL);\n        top.addView(smallButton("＋ NOVÝ OBVOD / PRVEK", C_ORANGE, C_TEXT, v -> measurementDialog(null, "CIRCUIT")), new LinearLayout.LayoutParams(0, dp(48), 2));\n        LinearLayout.LayoutParams bl = new LinearLayout.LayoutParams(0, dp(48), 1); bl.leftMargin = dp(7);\n        top.addView(smallButton("HROMADNĚ", C_DARK, Color.WHITE, v -> bulkDialog()), bl);\n        list.addView(top, marginBottom(dp(10)));\n        if (rows.isEmpty()) {\n            LinearLayout hint=card(); hint.addView(text("MĚŘENÍ ZAČÍNÁ OBVODEM / PRVKEM",15,C_TEXT,true));\n            hint.addView(text("Nejdříve založ obvod nebo zařízení. Teprve potom k němu přidávej měřicí body, spojitost a RCD / RCBO.",14,C_MUTED,false),marginTop(dp(7)));\n            list.addView(hint); detail.addView(text("Zatím není vytvořen žádný obvod ani prvek.",17,C_MUTED,false)); return;\n        }\n        Map<String,List<Db.Row>> children=new LinkedHashMap<>(); List<Db.Row> roots=new ArrayList<>();\n        for(Db.Row r:rows){\n            String pk=nz(r.get("parent_key")); Db.Row parent=null;\n            if(!pk.isEmpty()) for(Db.Row x:rows) if(pk.equals(nz(x.get("item_key")))){parent=x;break;}\n            if(parent==null) roots.add(r); else {List<Db.Row> kids=children.get(nodeKey(parent));if(kids==null){kids=new ArrayList<>();children.put(nodeKey(parent),kids);}kids.add(r);}\n        }\n        Db.Row active=null; for(Db.Row r:rows) if(r.id()==selectedMeasurementId){active=r;break;}\n        if(active==null){active=roots.get(0);selectedMeasurementId=active.id();}\n        for(Db.Row rootRow:roots) addTabletMeasurementGroup(list,rootRow,children,rootRow.id()==selectedMeasurementId);\n        final Db.Row chosen=active; String title=nz(chosen.get("element")); if(title.isEmpty())title=rowTypeLabel(measurementRowType(chosen));\n        detail.addView(text(title,22,C_TEXT,true),marginBottom(dp(4)));\n        detail.addView(pill(rowTypeLabel(measurementRowType(chosen)),rowTypeColor(measurementRowType(chosen)),Color.WHITE),marginBottom(dp(12)));\n        String kind=measurementRowType(chosen); Db.Row owner=chosen;\n        if(!isTreeParent(kind)&&!nz(chosen.get("parent_key")).isEmpty()) for(Db.Row x:rows) if(nz(chosen.get("parent_key")).equals(nz(x.get("item_key")))){owner=x;break;}\n        if(isTreeParent(measurementRowType(owner))){\n            final Db.Row parent=owner; detail.addView(text("Přidat měření k: "+(nz(parent.get("element")).isEmpty()?"prvku":parent.get("element")),14,C_MUTED,true),marginBottom(dp(7)));\n            addMeasurementQuickActions(detail,parent); List<Db.Row> kids=children.get(nodeKey(parent));\n            if(kids==null||kids.isEmpty()) detail.addView(text("Tento prvek zatím nemá žádné měřicí body.",14,C_MUTED,false),marginTop(dp(10)));\n            else { detail.addView(text("Měřicí body tohoto prvku",14,C_MUTED,true),marginTop(dp(12))); for(Db.Row child:kids){LinearLayout c=card();c.setClickable(true);c.setOnClickListener(v->{selectedMeasurementId=child.id();showMeasurements(false);});String ct=nz(child.get("element"));if(ct.isEmpty())ct=rowTypeLabel(measurementRowType(child));c.addView(text(ct,15,C_TEXT,true));String cv=valuesText(child);if(cv.isEmpty())cv="Zatím bez naměřené hodnoty";c.addView(text(cv,13,C_MUTED,false),marginTop(dp(4)));bodyAdd(detail,c,6);}}\n        } else {\n            LinearLayout values=measurementValueGrid(chosen); if(values.getChildCount()>0)detail.addView(values,marginBottom(dp(10)));else detail.addView(text("Hodnoty zatím nejsou vyplněné.",14,C_MUTED,false),marginBottom(dp(10)));\n            if(!nz(chosen.get("note")).isEmpty())detail.addView(text("Poznámka: "+chosen.get("note"),14,C_MUTED,false),marginBottom(dp(10)));\n        }\n        detail.addView(smallButton("UPRAVIT VYBRANOU POLOŽKU",C_ORANGE,C_TEXT,v->measurementDialog(chosen)),marginBottom(dp(8)));\n        detail.addView(smallButton("SMAZAT VYBRANOU POLOŽKU",Color.WHITE,C_RED,v->new AlertDialog.Builder(this).setTitle("Smazat položku?").setMessage("Smazat vybranou položku měření?").setNegativeButton("Ne",null).setPositiveButton("Ano",(d,w)->{db.deleteMeasurement(chosen.id());selectedMeasurementId=0;showMeasurements(false);}).show()),marginBottom(dp(8)));\n    }\n\n    private void addMeasurementQuickActions(LinearLayout detail, Db.Row parent){\n        String[] labels={"＋ MĚŘICÍ BOD","＋ SPOJITOST","＋ RCD / RCBO","＋ POZNÁMKA"}; String[] types={"POINT","CONTINUITY","RCD","NOTE"};\n        for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);for(int col=0;col<2;col++){int i=row*2+col;final String t=types[i];LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);if(col>0)lp.leftMargin=dp(7);line.addView(smallButton(labels[i],C_BG,C_TEXT,v->measurementDialog(null,t,parent)),lp);}detail.addView(line,marginBottom(dp(7)));}\n    }\n\n    private void addTabletMeasurementGroup(LinearLayout list, Db.Row root, Map<String,List<Db.Row>> children, boolean selected){\n        String rt=measurementRowType(root);List<Db.Row> kids=children.get(nodeKey(root));LinearLayout c=card();c.setClickable(true);c.setOnClickListener(v->{selectedMeasurementId=root.id();showMeasurements(false);});c.setBackground(rounded(selected?Color.rgb(255,243,220):Color.WHITE,selected?C_ORANGE:C_BORDER,12));\n        LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.HORIZONTAL);head.setGravity(Gravity.CENTER_VERTICAL);LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);String title=nz(root.get("element"));if(title.isEmpty())title="NOVÝ PRVEK";tx.addView(text(title,16,C_TEXT,true));int total=kids==null?0:kids.size(),done=0;if(kids!=null)for(Db.Row k:kids)if(k.bool("done"))done++;tx.addView(text(total==0?"Zatím bez měření":done+" / "+total+" podřízených měření hotovo",12,C_MUTED,false));head.addView(tx,new LinearLayout.LayoutParams(0,dp(50),1));head.addView(pill(rowTypeLabel(rt),rowTypeColor(rt),Color.WHITE),new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,dp(28)));c.addView(head);\n        if(kids!=null&&!kids.isEmpty()){LinearLayout summary=new LinearLayout(this);summary.setOrientation(LinearLayout.VERTICAL);summary.setPadding(dp(8),dp(6),dp(8),0);for(Db.Row k:kids){String t=nz(k.get("element"));if(t.isEmpty())t=rowTypeLabel(measurementRowType(k));String v=valuesText(k);if(v.isEmpty())v="—";TextView line=text("↳ "+t+"   "+v,12,C_TEXT,false);line.setMaxLines(2);summary.addView(line,marginBottom(dp(4)));}c.addView(summary);}\n        list.addView(c,marginBottom(dp(8)));\n    }\n\n    private void bodyAdd(LinearLayout parent, View child, int bottom){parent.addView(child,marginBottom(dp(bottom)));}\n\n'''
s=s[:s.index(start)]+method+s[end:]
