# SyncStore: LEFT JOIN so an anonymous revision is sent instead of disappearing.
replace('source/android/app/src/main/java/cz/pzrevize/mobile/SyncStore.java',"SELECT r.id,r.uuid,r.server_id,r.server_hash,r.revision_no,r.revision_type,r.object_name,r.object_address,r.status,r.note,r.updated_at,c.uuid AS customer_uuid,c.server_id AS customer_server_id,COALESCE(s.server_id,0) AS source_server_id FROM revisions r JOIN customers c ON c.id=r.customer_id LEFT JOIN revisions s ON s.id=r.source_revision_id WHERE r.dirty=1 ORDER BY r.id","SELECT r.id,r.uuid,r.server_id,r.server_hash,r.revision_no,r.revision_type,r.object_name,r.object_address,r.status,r.note,r.updated_at,COALESCE(c.uuid,'') AS customer_uuid,COALESCE(c.server_id,0) AS customer_server_id,COALESCE(s.server_id,0) AS source_server_id FROM revisions r LEFT JOIN customers c ON c.id=r.customer_id LEFT JOIN revisions s ON s.id=r.source_revision_id WHERE r.dirty=1 ORDER BY r.id",'revision sync left join')

