new='uuid=txt(o.get("uuid"));sid=as_int(o.get("server_id"));cid=as_int(o.get("customer_server_id")) or id_by_uuid.get(txt(o.get("customer_uuid")),0)\n                customer_value = cid if cid > 0 else None'
