ns=ns.replace(old,new,1).replace('vals=[cid,revno,txt(o.get("revision_type")) or "ELEKTRO",txt(o.get("status")) or "Rozpracovaná"]','vals=[customer_value,revno,txt(o.get("revision_type")) or "ELEKTRO",txt(o.get("status")) or "Rozpracovaná"]',1).replace('cols=["customer_id","revision_no","revision_type","status","created_at","updated_at"];vals=[cid,revno,txt(o.get("revision_type")) or "ELEKTRO",txt(o.get("status")) or "Rozpracovaná",now(),now()]','cols=["customer_id","revision_no","revision_type","status","created_at","updated_at"];vals=[customer_value,revno,txt(o.get("revision_type")) or "ELEKTRO",txt(o.get("status")) or "Rozpracovaná",now(),now()]',1)
p.write_text(ns,encoding='utf-8')

